// Turns an n8n execution failure into an alert log.
// Outputs structured alert so silent failures never happen.
const data = $json;
const execution = data.execution || {};
const workflow = data.workflow || {};
const error = execution.error || {};

const message = [
  '🚨 [LendLoop Automation Failure]',
  'Workflow: ' + (workflow.name || 'Unknown workflow'),
  'Failed node: ' + (execution.lastNodeExecuted || 'Unknown node'),
  'Error: ' + (error.message || 'Unknown error'),
  'Execution ID: ' + (execution.id || 'N/A'),
  'Retry Count: ' + (execution.retryOf || '0'),
].join('\n');

console.error('[LendLoop][ERROR_ALERT] ' + message.replace(/\n/g, ' | '));

return [{
  json: {
    message,
    workflow: workflow.name || null,
    executionId: execution.id || null,
    failedNode: execution.lastNodeExecuted || null,
    timestamp: new Date().toISOString()
  }
}];
